    },
    "exp_008a_no_subsample_dt2": {
        "dir": "exp_008a_fixed_dt2_no_subsample",
        "config": {"dt": 2, "subsample": False, "dt_embed": "untrained", "horizon": 15, "seed": 0}
    },
    "exp_008c_no_subsample_dt2_h8": {
        "dir": "exp_008c_fixed_dt2_no_subsample_h8",
        "config": {"dt": 2, "subsample": False, "dt_embed": "untrained", "horizon": 8, "seed": 0}
    },
    "exp_008d_subsample_on_h8": {
        "dir": "exp_008d_subsample_on_h8",
        "config": {"dt": 2, "subsample": True, "dt_embed": "trained", "horizon": 8, "seed": 0}
    },
    "exp_008e_v3_subsample_on_dt1_h15": {
        "dir": "exp_008e_v3_subsample_on_dt1_h15",
        "config": {"dt": 1, "subsample": True, "dt_embed": "untrained", "horizon": 15, "seed": 0}
    },
    "exp_008f_no_dt_embed_subsample_on_h8": {
        "dir": "exp_008f_no_dt_embed_subsample_on_h8",
        "config": {"dt": 2, "subsample": True, "dt_embed_dim": 0, "horizon": 8, "seed": 0}
    },
    "exp_009b_008d_walker_s2": {
        "dir": "exp_009b_008d_walker_s2",
        "config": {"dt": 2, "subsample": True, "dt_embed": "trained", "horizon": 8, "seed": 2}
    },
    "exp_009c_008f_walker_s2": {
        "dir": "exp_009c_008f_walker_s2",
        "config": {"dt": 2, "subsample": True, "dt_embed_dim": 0, "horizon": 8, "seed": 2}
    },
}

BASELINE_VE = {
    25000: 0.087, 35000: 0.241, 45000: 0.331, 55000: 0.404,
    65000: 0.563, 75000: 0.719, 85000: 0.701, 95000: 0.632,
    105000: 0.656
}

FIELDS = [
    "eval_return", "value_mean", "model_loss", "actor_loss",
    "actor_entropy", "gate_dt_mean", "gate_dt_std", "fps",
    "value_std", "target_mean", "target_std",
    "gate_dt_1_frac", "gate_dt_2_frac", "gate_dt_3_frac", "gate_dt_4_frac",
    "gate_empirical_entropy", "gate_entropy_ratio",
]

def load_metrics(exp_dir):
    path = os.path.join(LOGDIR, exp_dir, "metrics.jsonl")
    if not os.path.exists(path):
        return None
    step_data = defaultdict(dict)
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            row = json.loads(line)
            step = int(row.get("step", -1))
            if step < 0:
                continue
            for k, v in row.items():
                if k != "step":
                    step_data[step][k] = v
    return step_data

def extract_trajectory(step_data):
    trajectory = []
    sorted_steps = sorted(step_data.keys())
    if not sorted_steps:
        return trajectory
    target_steps = list(range(5000, sorted_steps[-1] + 10001, 10000))
    for ts in target_steps:
        if ts not in step_data:
            continue
        d = step_data[ts]
        if "eval_return" not in d:
            continue
        point = {"step": ts}
        er = d.get("eval_return")
        vm = d.get("value_mean")
        point["eval_return"] = round(er, 2) if er is not None else None
        point["value_mean"] = round(vm, 4) if vm is not None else None
        if er and vm and er != 0:
            point["ve_ratio"] = round(vm / er, 4)
        else:
            point["ve_ratio"] = None
        for f in ["model_loss", "actor_loss", "actor_entropy",
                   "gate_dt_mean", "gate_dt_std", "fps",
                   "gate_dt_1_frac", "gate_dt_2_frac", "gate_dt_3_frac", "gate_dt_4_frac",
                   "gate_empirical_entropy", "gate_entropy_ratio"]:
            v = d.get(f)
            if v is not None:
                point[f] = round(v, 4) if isinstance(v, float) else v
        trajectory.append(point)
    return trajectory

def compute_summary(trajectory, baseline_traj):
    if not trajectory:
        return {}
    evals = [(p["step"], p["eval_return"]) for p in trajectory if p.get("eval_return") is not None]
    ves = [(p["step"], p["ve_ratio"]) for p in trajectory if p.get("ve_ratio") is not None]
    if not evals:
        return {}
    peak = max(evals, key=lambda x: x[1])
    final = evals[-1]
    summary = {
        "peak_eval_return": round(peak[1], 2),
        "peak_step": peak[0],
        "final_eval_return": round(final[1], 2),
        "final_step": final[0],
        "total_eval_points": len(evals),
    }
    if ves:
        max_ve = max(ves, key=lambda x: x[1])
        summary["max_ve_ratio"] = round(max_ve[1], 4)
        summary["max_ve_step"] = max_ve[0]
        ve_at_45k = next((p["ve_ratio"] for p in trajectory if p["step"] == 45000 and p.get("ve_ratio") is not None), None)
        if ve_at_45k is not None:
            summary["ve_at_45K"] = round(ve_at_45k, 4)
            summary["normalized_ve_at_45K"] = round(ve_at_45k / 0.331, 4)
        ve_at_105k = next((p["ve_ratio"] for p in trajectory if p["step"] == 105000 and p.get("ve_ratio") is not None), None)
        if ve_at_105k is not None:
            summary["ve_at_105K"] = round(ve_at_105k, 4)
            summary["normalized_ve_at_105K"] = round(ve_at_105k / 0.656, 4)
    # vs baseline at same final step
    if baseline_traj:
        bl_at_final = next((p["eval_return"] for p in baseline_traj if p["step"] == final[0] and p.get("eval_return") is not None), None)
        if bl_at_final and bl_at_final != 0:
            summary["vs_baseline_pct"] = round((final[1] / bl_at_final - 1) * 100, 2)
            summary["baseline_eval_at_final_step"] = round(bl_at_final, 2)
    return summary

# Main
output = {
    "metadata": {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "baseline_105K_eval": 915.67,
        "environment": "walker_walk",
        "baseline_ve_reference": BASELINE_VE,
        "num_experiments": len(EXPERIMENTS),
    },
    "experiments": {}
}

baseline_traj = None
all_summaries = []

for exp_name, exp_info in EXPERIMENTS.items():
    d = exp_info["dir"]
    step_data = load_metrics(d)
    if step_data is None:
        print(f"[WARN] {exp_name} ({d}): metrics.jsonl not found", file=sys.stderr)
        continue
    trajectory = extract_trajectory(step_data)
    if not trajectory:
        print(f"[WARN] {exp_name} ({d}): no eval data points", file=sys.stderr)
        continue
    if exp_name == "exp_001_baseline":
        baseline_traj = trajectory
    output["experiments"][exp_name] = {
        "config": exp_info["config"],
        "dir_name": d,
        "trajectory": trajectory,
    }
    print(f"[OK] {exp_name} ({d}): {len(trajectory)} eval points, steps {trajectory[0]['step']}-{trajectory[-1]['step']}")

# Compute summaries after baseline is loaded
for exp_name in output["experiments"]:
    traj = output["experiments"][exp_name]["trajectory"]
    summary = compute_summary(traj, baseline_traj)
    output["experiments"][exp_name]["summary"] = summary
    all_summaries.append((exp_name, summary))

out_path = os.path.join(LOGDIR, "paper_data_walker_walk.json")
with open(out_path, "w") as f:
    json.dump(output, f, indent=2)
print(f"\nWrote {out_path} ({os.path.getsize(out_path)} bytes)")

# Print summary table
print("\n" + "="*120)
print(f"{'Experiment':<45} {'Peak Eval':>10} {'@Step':>8} {'Final Eval':>11} {'@Step':>8} {'Max V/E':>8} {'nVE@45K':>8} {'nVE@105K':>9} {'vs BL%':>8}")
print("-"*120)
for exp_name, s in all_summaries:
    if not s:
        continue
    peak = f"{s.get('peak_eval_return','')}"
    ps = f"{s.get('peak_step','')}"
    fe = f"{s.get('final_eval_return','')}"
    fs = f"{s.get('final_step','')}"
    mve = f"{s.get('max_ve_ratio','')}"
    nve45 = f"{s.get('normalized_ve_at_45K','')}"
    nve105 = f"{s.get('normalized_ve_at_105K','')}"
    vsbl = f"{s.get('vs_baseline_pct','')}"
    print(f"{exp_name:<45} {peak:>10} {ps:>8} {fe:>11} {fs:>8} {mve:>8} {nve45:>8} {nve105:>9} {vsbl:>8}")
print("="*120)
PYEOF
echo "Script written."
